 </div></section>
 <footer class="bottom"><div class="objective" id="objective">Your next small brave thing<strong id="objectiveText">Find a way into the cabinet.</strong></div><div class="inventory"><span class="inv-label">Pockets</span><div class="slot empty" data-slot="0" aria-label="Empty pocket"></div><div class="slot empty" data-slot="1" aria-label="Empty pocket"></div><div class="slot empty" data-slot="2" aria-label="Empty pocket"></div><div class="slot empty" data-slot="3" aria-label="Empty pocket"></div></div><div class="toggle-wrap"><button class="toggle" id="toggleBtn" aria-label="Toggle reality"><span class="toggle-title"><strong id="realityName">The Ward</strong><span id="realityHint">Tap to cross over</span></span><span class="switch"></span></button></div><div class="hint">Click things to look closer.<br><b>Take items · combine from your pockets</b></div></footer>
 </main>
 <script>
+const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
+let is_abyss_active=false; // The single source of truth for reality, visibility, and collision.
+let inventory=[],selected=null,threadedToy=false,shadowDistracted=false,cabinetUnlocked=false,heartFound=false,gameWon=false;
+let soundOn=true,audioCtx=null,typeTimer=null,dialogueQueue=[],typing=false,fullLine='',lineIndex=0,toastTimer;
+const game=$('#game'),textEl=$('#dialogueText'),speakerEl=$('#speaker');
+const itemMeta={toy:{name:'Tin Toy',icon:'<circle cx="16" cy="16" r="10" fill="#c45452" stroke="#d5bf89" stroke-width="3"/><path d="M16 5V2m-5 3 5-3 5 3M5 26h22" stroke="#d5bf89" stroke-width="2"/><circle cx="8" cy="28" r="3" fill="#403c3a"/><circle cx="24" cy="28" r="3" fill="#403c3a"/>'},thread:{name:'Red Thread',icon:'<path d="M4 23q12-22 8-7t10-7q9-8 1 4t5 13" fill="none" stroke="#e88a81" stroke-width="4" stroke-linecap="round"/><circle cx="28" cy="27" r="2" fill="#e88a81"/>'},'stitched-toy':{name:'Humming Toy',icon:'<circle cx="16" cy="17" r="9" fill="#bd514f" stroke="#d7c18e" stroke-width="3"/><path d="M16 8V3m-5 4 5-4 5 4M7 25l19-16m-4 3 4 3m-9 3 4 4M6 28h20" stroke="#dbba98" stroke-width="2.4" stroke-linecap="round"/>'},key:{name:'Bone Key',icon:'<circle cx="9" cy="11" r="6" fill="none" stroke="#e7c89b" stroke-width="4"/><path d="m13 15 13 13m-5-5 4-4m-7 1 4-4" stroke="#e7c89b" stroke-width="4" stroke-linecap="round"/>'},heart:{name:'Glass Heart',icon:'<path d="M16 29S3 20 4 11q1-9 11-4l1 2 2-2q10-4 11 5 1 8-13 17z" fill="#a84952" stroke="#eaa79a" stroke-width="2"/><path d="m10 11 5 4 4-4" fill="none" stroke="#ffd6b5" stroke-width="2"/>'}};
+function playTone(freq=280,duration=.08,type='sine',volume=.025){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch(e){}}
+function babble(){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const now=audioCtx.currentTime,o=audioCtx.createOscillator(),g=audioCtx.createGain(),f=audioCtx.createBiquadFilter();o.type='triangle';o.frequency.setValueAtTime(190+Math.random()*90,now);o.frequency.exponentialRampToValueAtTime(90+Math.random()*100,now+.13);f.type='lowpass';f.frequency.value=700;g.gain.setValueAtTime(.028,now);g.gain.exponentialRampToValueAtTime(.001,now+.14);o.connect(f);f.connect(g);g.connect(audioCtx.destination);o.start();o.stop(now+.15)}catch(e){}}
+function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+function say(speaker,line){speakerEl.textContent=speaker;fullLine=line;textEl.textContent='';typing=true;clearInterval(typeTimer);let i=0;typeTimer=setInterval(()=>{if(i<fullLine.length){textEl.textContent+=fullLine[i++];if(i%3===0)babble()}else{clearInterval(typeTimer);typing=false}},24)}
+function queue(lines){dialogueQueue.push(...lines);advanceDialogue()}
+function advanceDialogue(){if(typing){clearInterval(typeTimer);textEl.textContent=fullLine;typing=false;return}if(dialogueQueue.length){const [s,l]=dialogueQueue.shift();say(s,l)}}
+$('#dialogue').addEventListener('click',advanceDialogue);
+function icon(item){return `<svg viewBox="0 0 32 32" aria-hidden="true">${itemMeta[item].icon}</svg>`}
+function renderInventory(){const slots=$$('.slot');slots.forEach((s,i)=>{const item=inventory[i];s.classList.toggle('empty',!item);s.classList.toggle('selected',!!item&&item===selected);s.innerHTML=item?`${icon(item)}<span>${itemMeta[item].name}</span>`:'';s.setAttribute('aria-label',item?`${itemMeta[item].name}${selected===item?', selected':''}`:'Empty pocket')})}
+function addItem(item){if(inventory.includes(item))return;inventory.push(item);renderInventory();playTone(540,.14,'sine',.04);toast(`${itemMeta[item].name} tucked away`)}
+function removeItem(item){inventory=inventory.filter(x=>x!==item);if(selected===item)selected=null;renderInventory()}
+function updateObjective(){let objective='Find a way into the cabinet.';if(inventory.includes('toy')&&inventory.includes('thread'))objective='Make a toy that can sing.';if(threadedToy&&!shadowDistracted)objective='Give the shadow something else to listen to.';if(shadowDistracted&&!inventory.includes('key')&&!cabinetUnlocked)objective='Take the bone key from the cabinet ledge.';if(inventory.includes('key')&&!cabinetUnlocked)objective='Unlock the medicine cabinet in the ward.';if(cabinetUnlocked&&!heartFound)objective='Look inside the cabinet in the Abyss.';if(heartFound&&!gameWon)objective='Return the glass heart to Mara.';$('#objectiveText').textContent=objective}
+function setReality(next){is_abyss_active=next;game.classList.toggle('abyss',is_abyss_active);$('#realityName').textContent=is_abyss_active?'The Abyss':'The Ward';$('#realityHint').textContent=is_abyss_active?'Nothing stays buried':'Tap to cross over';playTone(is_abyss_active?105:390,.28,'sine',.05);if(is_abyss_active){queue([['Mara','The walls are breathing again. They only do that when something is listening.']])}else{queue([['Mara','Back where the corners behave. For now.']])}}
+$('#toggleBtn').addEventListener('click',()=>setReality(!is_abyss_active));
+function showHelp(){queue([['Moth','Click the room to investigate. The brass button swaps realities. Some things only have bodies on one side.'],['Mara','Take the toy and the red thread. Select one pocket, then the other to stitch them together. Use the humming toy on the shadow.']])}
+$('#helpBtn').addEventListener('click',showHelp);
+$('#soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.innerHTML=soundOn?'♫ &nbsp; SOUND ON':'♫ &nbsp; SOUND OFF';if(soundOn)playTone(500,.1)});

