input.newString:
$('#soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.innerHTML=soundOn?'♫ &nbsp; SOUND ON':'♫ &nbsp; SOUND OFF';if(soundOn)playTone(500,.1)});
function interact(id){
 if(id==='cabinetNormal'){queue([['Mara',cabinetUnlocked?'The cabinet is open. The mirror is smiling at the wrong girl.':'Locked. The keyhole looks almost… tooth-shaped.']]);return}
 if(id==='cabinetAbyss'){if(!shadowDistracted){queue([['Mara','A dark shape has its hand over the cabinet. It is humming to itself.']]);return}if(!cabinetUnlocked){queue([['Mara','The bone key fits. The cabinet opens with a wet little sigh.']]);cabinetUnlocked=true;updateObjective();return}if(!heartFound){heartFound=true;addItem('heart');queue([['Mara','A glass heart, still warm. I think it has been waiting for me.']]);updateObjective()}else queue([['Mara','Only my reflection now. She looks a little less afraid.']]);return}
 if(id==='toyNormal'){if(inventory.includes('toy')){queue([['Mara','It used to play a song. Now it only knows how to shiver.']]);return}addItem('toy');queue([['Mara','A tin toy, left behind by someone who thought they were coming back.']]);updateObjective();return}
 if(id==='threadAbyss'){if(inventory.includes('thread')){queue([['Mara','The red thread is already in my pocket. It feels warm.']]);return}addItem('thread');queue([['Mara','A strand of red thread. It twitches when I look away.']]);updateObjective();return}
 if(id==='keyAbyss'){if(!shadowDistracted){queue([['Mara','The key is just beyond the shadow’s hand. I need it to look somewhere else.']]);return}if(inventory.includes('key')){queue([['Mara','I have the bone key.']]);return}addItem('key');queue([['Mara','A key made from something that used to be alive.']]);updateObjective();return}
 if(id==='shadowAbyss'){if(shadowDistracted){queue([['Moth','Mrrr-ow. It is listening to its own song now. We can be quick.']]);return}if(!threadedToy){queue([['Mara','It has no face, but I can feel it listening. I need a sound to draw it away.']]);return}shadowDistracted=true;$('#shadowAbyss').style.opacity='.08';$('#shadowAbyss').style.pointerEvents='none';queue([['Moth','Mrrr-ow, little shadow. Listen to the pretty song.'],['Mara','It turned toward the music. The key is there on the ledge.']]);updateObjective();playTone(740,.2,'triangle',.045);return}
 if(id==='catNormal'||id==='catAbyss'){if(threadedToy&&!shadowDistracted){queue([['Moth','Mrrr-ow! I can smell the red thread on your hands. Tie it around the toy. Make it sing.']]);return}queue([['Moth',is_abyss_active?'Mrrr-ow. It wants the heart back. It says it remembers the beat.':'Mrrrow. The dark has a long, long tail. Don’t step on it.']]);return}
 if(id==='noteNormal'||id==='noteAbyss'){queue([['Mara',is_abyss_active?'The wall says: “SHE IS STILL SLEEPING.” I wish it would stop using my handwriting.':'A scrap of paper: “When the clock forgets, ask the cat what it heard.”']]);return}
 if(id==='heart'&&inventory.includes('heart')){if(!gameWon){gameWon=true;$('#ending').classList.add('show');playTone(650,.6,'sine',.04)}return}
}

